import { field, textarea, select, checkbox, htmlEscape, attrEscape, normalizeUrl } from "../tool-core.js";export default {form: `<div class="field-grid">${select({ id: "fpType", label: "Resource type", options: [{label:"img (image)",value:"img"},{label:"link (stylesheet)",value:"link"},{label:"script",value:"script"}], value: "img"})}${select({ id: "fpUseCase", label: "Use case", options: [{label:"LCP hero image",value:"lcp"},{label:"Above-the-fold critical",value:"critical"},{label:"Below-the-fold",value:"below"},{label:"Footer / non-critical",value:"low"}], value: "lcp"})}${field({ id: "fpSrc", label: "Resource URL", value: "/assets/hero.webp" })}</div>`,generate(root) {const type = root.querySelector("#fpType").value;const useCase = root.querySelector("#fpUseCase").value;const src = root.querySelector("#fpSrc").value.trim();let fpValue;if (useCase === "lcp" || useCase === "critical") {fpValue = "high";} else if (useCase === "low") {fpValue = "low";} else {fpValue = "auto";}let tag;if (type === "img") {tag = `<img src="${attrEscape(src)}" fetchpriority="${fpValue}" width="..." height="..." alt="...">`;} else if (type === "link") {tag = `<link rel="stylesheet" href="${attrEscape(src)}" fetchpriority="${fpValue}">`;} else {tag = `<script src="${attrEscape(src)}" fetchpriority="${fpValue}"><\/script>`;}let note = "\n\n/* Usage note: ";if (type === "img") {note += "Place this img tag in your page body where the image should appear.\n";} else if (type === "link") {note += "Place this link tag in the <head> of your document.\n";} else {note += "Place this script tag near the end of <body> or in <head> with defer/async.\n";}if (useCase === "lcp") {note += " This is an LCP candidate. Do NOT add loading=\"lazy\" to this element.\n";} else if (useCase === "low") {note += " Consider adding loading=\"lazy\" for images in this category.\n";} else {note += " Combine with loading=\"lazy\" or \"eager\" as appropriate.\n";}note += " Only use fetchpriority on the most critical resource to avoid prioritization dilution. */";return { output: tag + note };}};